fn get_score(player: Int) -> Option[Int] {
  if player > 0 { return Some(player * 10); }
  return None;
}

fn display_score(score: Option[Int]) -> Str {
  return score.unwrap_or(0).to_str();
}

fn best_of_three(a: Option[Int], b: Option[Int], c: Option[Int]) -> Int {
  let va = a.unwrap_or(0);
  let vb = b.unwrap_or(0);
  let vc = c.unwrap_or(0);
  var max = va;
  if vb > max { max = vb; }
  if vc > max { max = vc; }
  return max;
}

fn main() -> Int {
  return best_of_three(Some(10), None, Some(7));
}
